// Seat class drives the base fare.
enum SeatClass {
    ECONOMY, // cheaper, larger capacity
    BUSINESS // pricier, smaller capacity
}

// Lifecycle status of a single seat.
enum SeatStatus {
    AVAILABLE, // free to be booked
    BOOKED     // currently assigned to a passenger
}

// A single physical seat on a flight.
class Seat {
    private final String seatId;      // unique id, e.g. E1
    private final SeatClass seatClass; // pricing/class tier
    private SeatStatus status;        // current lifecycle state

    public Seat(String seatId, SeatClass seatClass) {
        this.seatId = seatId;         // store id
        this.seatClass = seatClass;   // store class
        this.status = SeatStatus.AVAILABLE; // new seats start free
    }

    public String getSeatId() { return seatId; }         // id getter
    public SeatClass getSeatClass() { return seatClass; } // class getter
    public SeatStatus getStatus() { return status; }      // status getter
    public void setStatus(SeatStatus status) { this.status = status; } // status setter
    public boolean isAvailable() { return status == SeatStatus.AVAILABLE; } // convenience check
}

// Creates seats with class-prefixed ids for a flight.
class SeatFactory {
    private final java.util.Map<String, Integer> counters = new java.util.HashMap<>(); // prefix -> count so far

    public java.util.List<Seat> createSeats(SeatClass seatClass, int count) {
        String prefix = seatClass == SeatClass.ECONOMY ? "E" : "B"; // pick prefix by class
        java.util.List<Seat> created = new java.util.ArrayList<>(); // result list
        for (int i = 0; i < count; i++) {                            // create 'count' seats
            int n = counters.getOrDefault(prefix, 0) + 1;             // next number for this prefix
            counters.put(prefix, n);                                   // remember it
            created.add(new Seat(prefix + n, seatClass));              // e.g. E1
        }
        return created; // hand back the new seats
    }
}

