// Strategy interface: how a fare is computed from current demand.
interface FlightPricingStrategy {
    double calculateFare(SeatClass seatClass, int soldCount, int capacity);
}

// Demand-based pricing: higher fare as a class fills up.
class DemandBasedPricingStrategy implements FlightPricingStrategy {
    private double baseFare(SeatClass seatClass) {
        return seatClass == SeatClass.ECONOMY ? 100.0 : 300.0; // base fare per class
    }

    @Override
    public double calculateFare(SeatClass seatClass, int soldCount, int capacity) {
        double base = baseFare(seatClass);           // starting fare
        double soldRatio = (double) soldCount / capacity; // how full the class is before this booking
        double multiplier;                             // demand multiplier
        if (soldRatio < 0.5) {                          // low demand tier
            multiplier = 1.0;
        } else if (soldRatio < 0.8) {                    // medium demand tier
            multiplier = 1.2;
        } else {                                          // high demand tier
            multiplier = 1.5;
        }
        return base * multiplier; // final fare
    }
}

