interface BookingObserver {
    void onBookingConfirmed(Booking booking);   // seat assigned
    void onBookingWaitlisted(Booking booking);  // no seat, joined waitlist
    void onBookingCancelled(Booking booking);   // booking cancelled
    void onWaitlistPromoted(Booking booking);   // waitlisted booking got a seat
}

