// The core orchestrator tying every piece together.
class AirlineBookingService {
    private final java.util.Map<String, Seat> seats = new java.util.HashMap<>();          // seatId -> Seat
    private final java.util.Map<String, Booking> bookings = new java.util.HashMap<>();    // bookingId -> Booking
    private final java.util.Map<SeatClass, java.util.List<Booking>> waitlists = new java.util.HashMap<>(); // per-class FIFO queue
    private final java.util.Map<SeatClass, Integer> capacity = new java.util.HashMap<>();  // total seats per class
    private final int waitlistLimit;                     // max waitlisted per class
    private final FlightPricingStrategy pricingStrategy;  // pluggable pricing
    private final java.util.List<BookingObserver> observers = new java.util.ArrayList<>(); // listeners
    private int bookingCounter = 0; // simple id generator

    public AirlineBookingService(FlightPricingStrategy pricingStrategy, int waitlistLimit) {
        this.pricingStrategy = pricingStrategy; // store chosen strategy
        this.waitlistLimit = waitlistLimit;      // store waitlist bound
        waitlists.put(SeatClass.ECONOMY, new java.util.ArrayList<>()); // init economy queue
        waitlists.put(SeatClass.BUSINESS, new java.util.ArrayList<>()); // init business queue
    }

    public void addSeats(java.util.List<Seat> newSeats) {
        for (Seat s : newSeats) {                          // register each seat
            seats.put(s.getSeatId(), s);                     // store by id
            capacity.merge(s.getSeatClass(), 1, Integer::sum); // bump class capacity
        }
    }

    public void addObserver(BookingObserver observer) { observers.add(observer); } // register a listener

    private int soldCount(SeatClass seatClass) {
        int count = 0;                                      // running total
        for (Seat s : seats.values()) {                       // scan all seats
            if (s.getSeatClass() == seatClass && s.getStatus() == SeatStatus.BOOKED) count++; // count booked ones
        }
        return count; // total sold in this class
    }

    // Books a seat if one is free, else waitlists, else throws.
    public synchronized Booking bookSeat(String passengerId, SeatClass seatClass) {
        Seat freeSeat = null;                                // will hold a free seat if found
        for (Seat s : seats.values()) {                       // scan all seats
            if (s.getSeatClass() == seatClass && s.isAvailable()) { // match class and free
                freeSeat = s;                                   // remember it
                break;                                            // stop at first match
            }
        }
        bookingCounter++;                                     // bump id counter
        String bookingId = "BK-" + bookingCounter;              // build id
        Booking booking = new Booking(bookingId, passengerId, seatClass); // build booking
        if (freeSeat != null) {                                // a seat is free
            int sold = soldCount(seatClass);                     // demand before this booking
            double fare = pricingStrategy.calculateFare(seatClass, sold, capacity.get(seatClass)); // compute fare
            freeSeat.setStatus(SeatStatus.BOOKED);                // claim the seat
            booking.setSeatId(freeSeat.getSeatId());               // link seat
            booking.setFare(fare);                                  // set fare
            booking.setStatus("CONFIRMED");                         // confirmed
            bookings.put(bookingId, booking);                       // store it
            for (BookingObserver obs : observers) obs.onBookingConfirmed(booking); // notify
            return booking; // hand back to caller
        }
        java.util.List<Booking> queue = waitlists.get(seatClass); // this class's waitlist
        if (queue.size() >= waitlistLimit) {                       // waitlist also full
            for (BookingObserver obs : observers) obs.onBookingCancelled(booking); // treat as immediately failed
            throw new SeatClassFullException("No " + seatClass + " seat or waitlist slot available");
        }
        booking.setStatus("WAITLISTED");                           // waitlisted
        bookings.put(bookingId, booking);                           // store it
        queue.add(booking);                                          // enqueue FIFO
        for (BookingObserver obs : observers) obs.onBookingWaitlisted(booking); // notify
        return booking; // hand back to caller
    }

    // Cancels a booking; if it held a seat, promotes the next waitlisted passenger into it.
    public synchronized void cancelBooking(String bookingId) {
        Booking booking = bookings.get(bookingId);                 // look up booking
        if (booking == null || booking.getStatus().equals("CANCELLED")) {
            throw new BookingNotFoundException("Unknown or already-cancelled booking: " + bookingId);
        }
        if ("WAITLISTED".equals(booking.getStatus())) {              // simple case: just dequeue
            waitlists.get(booking.getSeatClass()).remove(booking);    // remove from queue
            booking.setStatus("CANCELLED");                           // mark cancelled
            for (BookingObserver obs : observers) obs.onBookingCancelled(booking); // notify
            return;
        }
        Seat seat = seats.get(booking.getSeatId());                  // the seat this booking held
        seat.setStatus(SeatStatus.AVAILABLE);                         // free it
        booking.setStatus("CANCELLED");                                // mark cancelled
        for (BookingObserver obs : observers) obs.onBookingCancelled(booking); // notify
        java.util.List<Booking> queue = waitlists.get(booking.getSeatClass()); // this class's waitlist
        if (!queue.isEmpty()) {                                        // someone is waiting
            Booking promoted = queue.remove(0);                          // longest-waiting entry
            int sold = soldCount(booking.getSeatClass());                 // demand right now
            double fare = pricingStrategy.calculateFare(booking.getSeatClass(), sold, capacity.get(booking.getSeatClass())); // fresh fare
            seat.setStatus(SeatStatus.BOOKED);                            // claim the freed seat
            promoted.setSeatId(seat.getSeatId());                          // link seat
            promoted.setFare(fare);                                         // set fare
            promoted.setStatus("CONFIRMED");                                // confirmed
            for (BookingObserver obs : observers) obs.onWaitlistPromoted(promoted); // notify
        }
    }
}

