#include <memory>
#include <algorithm>
#include <stdexcept>
#include <iostream>
using namespace std;

// Observer interface: reacts to booking lifecycle events.
class BookingObserver {
public:
    virtual void onBookingConfirmed(const Booking& booking) = 0;
    virtual void onBookingWaitlisted(const Booking& booking) = 0;
    virtual void onBookingCancelled(const Booking& booking) = 0;
    virtual void onWaitlistPromoted(const Booking& booking) = 0;
    virtual ~BookingObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleBookingObserver : public BookingObserver {
public:
    void onBookingConfirmed(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " confirmed for " << booking.passengerId << ", seat " << booking.seatId << ", fare " << booking.fare << endl;
    }
    void onBookingWaitlisted(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " waitlisted for " << booking.passengerId << endl;
    }
    void onBookingCancelled(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " cancelled for " << booking.passengerId << endl;
    }
    void onWaitlistPromoted(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " promoted for " << booking.passengerId << ", seat " << booking.seatId << ", fare " << booking.fare << endl;
    }
};

// Custom exceptions for the realistic failure modes.
class SeatClassFullException : public runtime_error {
public: SeatClassFullException(const string& msg) : runtime_error(msg) {}
};
class InvalidBookingException : public runtime_error {
public: InvalidBookingException(const string& msg) : runtime_error(msg) {}
};
class BookingNotFoundException : public runtime_error {
public: BookingNotFoundException(const string& msg) : runtime_error(msg) {}
};

// The core orchestrator tying every piece together.
class AirlineBookingService {
    map<string, Seat> seats;                       // seatId -> Seat
    map<string, Booking> bookings;                 // bookingId -> Booking
    map<SeatClass, vector<string>> waitlists;      // per-class FIFO queue of bookingIds
    map<SeatClass, int> capacity;                   // total seats per class
    int waitlistLimit;                               // max waitlisted per class
    shared_ptr<FlightPricingStrategy> pricingStrategy; // pluggable pricing
    vector<shared_ptr<BookingObserver>> observers;    // listeners
    int bookingCounter = 0;                            // simple id generator

    int soldCount(SeatClass seatClass) {
        int count = 0;                                  // running total
        for (auto& entry : seats) {                       // scan all seats
            if (entry.second.seatClass == seatClass && entry.second.status == SeatStatus::BOOKED) count++; // count booked ones
        }
        return count; // total sold in this class
    }

public:
    AirlineBookingService(shared_ptr<FlightPricingStrategy> strategy, int limit)
        : waitlistLimit(limit), pricingStrategy(strategy) {
        waitlists[SeatClass::ECONOMY] = {};  // init economy queue
        waitlists[SeatClass::BUSINESS] = {}; // init business queue
    }

    void addSeats(vector<Seat> newSeats) {
        for (auto& s : newSeats) {                        // register each seat
            seats.insert({s.seatId, s});                    // store by id
            capacity[s.seatClass] = capacity[s.seatClass]+1; // bump class capacity
        }
    }

    void addObserver(shared_ptr<BookingObserver> observer) { observers.push_back(observer); } // register a listener

    Booking bookSeat(string passengerId, SeatClass seatClass) {
        string freeSeatId = "";                            // will hold a free seat id if found
        for (auto& entry : seats) {                          // scan all seats
            if (entry.second.seatClass == seatClass && entry.second.isAvailable()) { // match class and free
                freeSeatId = entry.first;                       // remember it
                break;                                             // stop at first match
            }
        }
        bookingCounter++;                                    // bump id counter
        string bookingId = "BK-" + to_string(bookingCounter);  // build id
        Booking booking(bookingId, passengerId, seatClass);     // build booking
        if (!freeSeatId.empty()) {                              // a seat is free
            int sold = soldCount(seatClass);                       // demand before this booking
            double fare = pricingStrategy->calculateFare(seatClass, sold, capacity[seatClass]); // compute fare
            seats.at(freeSeatId).status = SeatStatus::BOOKED;       // claim the seat
            booking.seatId = freeSeatId;                              // link seat
            booking.fare = fare;                                        // set fare
            booking.status = "CONFIRMED";                                // confirmed
            bookings.insert({bookingId, booking});                        // store it
            for (auto& obs : observers) obs->onBookingConfirmed(booking); // notify
            return booking; // hand back to caller
        }
        auto& queue = waitlists[seatClass]; // this class's waitlist
        if ((int)queue.size() >= waitlistLimit) { // waitlist also full
            for (auto& obs : observers) obs->onBookingCancelled(booking); // treat as immediately failed
            throw SeatClassFullException("No seat or waitlist slot available");
        }
        booking.status = "WAITLISTED";       // waitlisted
        bookings.insert({bookingId, booking}); // store it
        queue.push_back(bookingId);             // enqueue FIFO
        for (auto& obs : observers) obs->onBookingWaitlisted(booking); // notify
        return booking; // hand back to caller
    }

    void cancelBooking(string bookingId) {
        auto it = bookings.find(bookingId); // look up booking
        if (it == bookings.end() || it->second.status == "CANCELLED") {
            throw BookingNotFoundException("Unknown or already-cancelled booking: " + bookingId);
        }
        Booking& booking = it->second;
        if (booking.status == "WAITLISTED") { // simple case: just dequeue
            auto& queue = waitlists[booking.seatClass];
            queue.erase(remove(queue.begin(), queue.end(), bookingId), queue.end()); // remove from queue
            booking.status = "CANCELLED";                                              // mark cancelled
            for (auto& obs : observers) obs->onBookingCancelled(booking); // notify
            return;
        }
        Seat& seat = seats.at(booking.seatId); // the seat this booking held
        seat.status = SeatStatus::AVAILABLE;     // free it
        booking.status = "CANCELLED";             // mark cancelled
        for (auto& obs : observers) obs->onBookingCancelled(booking); // notify
        auto& queue = waitlists[booking.seatClass]; // this class's waitlist
        if (!queue.empty()) {                          // someone is waiting
            string promotedId = queue.front();            // longest-waiting entry
            queue.erase(queue.begin());                     // dequeue it
            Booking& promoted = bookings.at(promotedId);
            int sold = soldCount(booking.seatClass);          // demand right now
            double fare = pricingStrategy->calculateFare(booking.seatClass, sold, capacity[booking.seatClass]); // fresh fare
            seat.status = SeatStatus::BOOKED;                  // claim the freed seat
            promoted.seatId = seat.seatId;                       // link seat
            promoted.fare = fare;                                  // set fare
            promoted.status = "CONFIRMED";                          // confirmed
            for (auto& obs : observers) obs->onWaitlistPromoted(promoted); // notify
        }
    }
};

