class AirlineBookingService {
    private final Map<String, Seat> seats = new HashMap<>();
    private final Map<String, Booking> bookings = new HashMap<>();
    private final Map<SeatClass, List<Booking>> waitlists = new HashMap<>();
    private final Map<SeatClass, Integer> capacity = new HashMap<>();
    private final int waitlistLimit;
    private final FlightPricingStrategy pricingStrategy;
    private final List<BookingObserver> observers = new ArrayList<>();
    private int bookingCounter = 0;

    public AirlineBookingService(FlightPricingStrategy pricingStrategy, int waitlistLimit) {
        this.pricingStrategy = pricingStrategy;
        this.waitlistLimit = waitlistLimit;
        waitlists.put(SeatClass.ECONOMY, new ArrayList<>());
        waitlists.put(SeatClass.BUSINESS, new ArrayList<>());
    }

    public void addSeats(List<Seat> newSeats) {
        for (Seat s : newSeats) {
            seats.put(s.getSeatId(), s);
            capacity.merge(s.getSeatClass(), 1, Integer::sum);
        }
    }

    public void addObserver(BookingObserver observer) { observers.add(observer); }

    private int soldCount(SeatClass seatClass) {
        int count = 0;
        for (Seat s : seats.values()) {
            if (s.getSeatClass() == seatClass && s.getStatus() == SeatStatus.BOOKED) count++;
        }
        return count;
    }

    public synchronized Booking bookSeat(String passengerId, SeatClass seatClass) {
        Seat freeSeat = null;
        for (Seat s : seats.values()) {
            if (s.getSeatClass() == seatClass && s.isAvailable()) {
                freeSeat = s;
                break;
            }
        }
        bookingCounter++;
        String bookingId = "BK-" + bookingCounter;
        Booking booking = new Booking(bookingId, passengerId, seatClass);
        if (freeSeat != null) {
            int sold = soldCount(seatClass);
            double fare = pricingStrategy.calculateFare(seatClass, sold, capacity.get(seatClass));
            freeSeat.setStatus(SeatStatus.BOOKED);
            booking.setSeatId(freeSeat.getSeatId());
            booking.setFare(fare);
            booking.setStatus("CONFIRMED");
            bookings.put(bookingId, booking);
            for (BookingObserver obs : observers) obs.onBookingConfirmed(booking);
            return booking;
        }
        List<Booking> queue = waitlists.get(seatClass);
        if (queue.size() >= waitlistLimit) {
            for (BookingObserver obs : observers) obs.onBookingCancelled(booking);
            throw new SeatClassFullException("No " + seatClass + " seat or waitlist slot available");
        }
        booking.setStatus("WAITLISTED");
        bookings.put(bookingId, booking);
        queue.add(booking);
        for (BookingObserver obs : observers) obs.onBookingWaitlisted(booking);
        return booking;
    }

    public synchronized void cancelBooking(String bookingId) {
        Booking booking = bookings.get(bookingId);
        if (booking == null || booking.getStatus().equals("CANCELLED")) {
            throw new BookingNotFoundException("Unknown or already-cancelled booking: " + bookingId);
        }
        if ("WAITLISTED".equals(booking.getStatus())) {
            waitlists.get(booking.getSeatClass()).remove(booking);
            booking.setStatus("CANCELLED");
            for (BookingObserver obs : observers) obs.onBookingCancelled(booking);
            return;
        }
        Seat seat = seats.get(booking.getSeatId());
        seat.setStatus(SeatStatus.AVAILABLE);
        booking.setStatus("CANCELLED");
        for (BookingObserver obs : observers) obs.onBookingCancelled(booking);
        List<Booking> queue = waitlists.get(booking.getSeatClass());
        if (!queue.isEmpty()) {
            Booking promoted = queue.remove(0);
            int sold = soldCount(booking.getSeatClass());
            double fare = pricingStrategy.calculateFare(booking.getSeatClass(), sold, capacity.get(booking.getSeatClass()));
            seat.setStatus(SeatStatus.BOOKED);
            promoted.setSeatId(seat.getSeatId());
            promoted.setFare(fare);
            promoted.setStatus("CONFIRMED");
            for (BookingObserver obs : observers) obs.onWaitlistPromoted(promoted);
        }
    }
}

