#include <stdexcept>
using namespace std;

enum class SeatClass { ECONOMY, BUSINESS };
enum class SeatStatus { AVAILABLE, BOOKED };

class Seat {
public:
    string seatId;
    SeatClass seatClass;
    SeatStatus status;

    Seat() {}
    Seat(string id, SeatClass cls) : seatId(id), seatClass(cls), status(SeatStatus::AVAILABLE) {}

    bool isAvailable() const { return status == SeatStatus::AVAILABLE; }
};

class SeatFactory {
    map<string, int> counters;

public:
    vector<Seat> createSeats(SeatClass seatClass, int count) {
        string prefix = (seatClass == SeatClass::ECONOMY) ? "E" : "B";
        vector<Seat> created;
        for (int i = 0; i < count; i++) {
            int n = counters[prefix] + 1;
            counters[prefix] = n;
            created.push_back(Seat(prefix + to_string(n), seatClass));
        }
        return created;
    }
};

class FlightPricingStrategy {
public:
    virtual double calculateFare(SeatClass seatClass, int soldCount, int capacity) = 0;
    virtual ~FlightPricingStrategy() {}
};

class DemandBasedPricingStrategy : public FlightPricingStrategy {
    double baseFare(SeatClass seatClass) {
        return (seatClass == SeatClass::ECONOMY) ? 100.0 : 300.0;
    }

public:
    double calculateFare(SeatClass seatClass, int soldCount, int capacity) override {
        double base = baseFare(seatClass);
        double soldRatio = (double)soldCount / capacity;
        double multiplier;
        if (soldRatio < 0.5) {
            multiplier = 1.0;
        } else if (soldRatio < 0.8) {
            multiplier = 1.2;
        } else {
            multiplier = 1.5;
        }
        return base * multiplier;
    }
};

class Passenger {
public:
    string passengerId;
    string name;

    Passenger() {}
    Passenger(string id, string n) : passengerId(id), name(n) {}
};

class Booking {
public:
    string bookingId;
    string passengerId;
    string seatId;
    SeatClass seatClass;
    double fare;
    string status;

    Booking() : fare(0.0) {}
    Booking(string id, string passId, SeatClass cls)
        : bookingId(id), passengerId(passId), seatId(""), seatClass(cls), fare(0.0), status("PENDING") {}
};

class BookingObserver {
public:
    virtual void onBookingConfirmed(const Booking& booking) = 0;
    virtual void onBookingWaitlisted(const Booking& booking) = 0;
    virtual void onBookingCancelled(const Booking& booking) = 0;
    virtual void onWaitlistPromoted(const Booking& booking) = 0;
    virtual ~BookingObserver() {}
};

class ConsoleBookingObserver : public BookingObserver {
public:
    void onBookingConfirmed(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " confirmed for " << booking.passengerId << ", seat " << booking.seatId << ", fare " << booking.fare << endl;
    }
    void onBookingWaitlisted(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " waitlisted for " << booking.passengerId << endl;
    }
    void onBookingCancelled(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " cancelled for " << booking.passengerId << endl;
    }
    void onWaitlistPromoted(const Booking& booking) override {
        cout << "Booking " << booking.bookingId << " promoted for " << booking.passengerId << ", seat " << booking.seatId << ", fare " << booking.fare << endl;
    }
};

class SeatClassFullException : public runtime_error {
public: SeatClassFullException(const string& msg) : runtime_error(msg) {}
};
class InvalidBookingException : public runtime_error {
public: InvalidBookingException(const string& msg) : runtime_error(msg) {}
};
class BookingNotFoundException : public runtime_error {
public: BookingNotFoundException(const string& msg) : runtime_error(msg) {}
};

class AirlineBookingService {
    map<string, Seat> seats;
    map<string, Booking> bookings;
    map<SeatClass, vector<string>> waitlists;
    map<SeatClass, int> capacity;
    int waitlistLimit;
    shared_ptr<FlightPricingStrategy> pricingStrategy;
    vector<shared_ptr<BookingObserver>> observers;
    int bookingCounter = 0;

    int soldCount(SeatClass seatClass) {
        int count = 0;
        for (auto& entry : seats) {
            if (entry.second.seatClass == seatClass && entry.second.status == SeatStatus::BOOKED) count++;
        }
        return count;
    }

public:
    AirlineBookingService(shared_ptr<FlightPricingStrategy> strategy, int limit)
        : waitlistLimit(limit), pricingStrategy(strategy) {
        waitlists[SeatClass::ECONOMY] = {};
        waitlists[SeatClass::BUSINESS] = {};
    }

    void addSeats(vector<Seat> newSeats) {
        for (auto& s : newSeats) {
            seats.insert({s.seatId, s});
            capacity[s.seatClass] = capacity[s.seatClass]+1;
        }
    }

    void addObserver(shared_ptr<BookingObserver> observer) { observers.push_back(observer); }

    Booking bookSeat(string passengerId, SeatClass seatClass) {
        string freeSeatId = "";
        for (auto& entry : seats) {
            if (entry.second.seatClass == seatClass && entry.second.isAvailable()) {
                freeSeatId = entry.first;
                break;
            }
        }
        bookingCounter++;
        string bookingId = "BK-" + to_string(bookingCounter);
        Booking booking(bookingId, passengerId, seatClass);
        if (!freeSeatId.empty()) {
            int sold = soldCount(seatClass);
            double fare = pricingStrategy->calculateFare(seatClass, sold, capacity[seatClass]);
            seats.at(freeSeatId).status = SeatStatus::BOOKED;
            booking.seatId = freeSeatId;
            booking.fare = fare;
            booking.status = "CONFIRMED";
            bookings.insert({bookingId, booking});
            for (auto& obs : observers) obs->onBookingConfirmed(booking);
            return booking;
        }
        auto& queue = waitlists[seatClass];
        if ((int)queue.size() >= waitlistLimit) {
            for (auto& obs : observers) obs->onBookingCancelled(booking);
            throw SeatClassFullException("No seat or waitlist slot available");
        }
        booking.status = "WAITLISTED";
        bookings.insert({bookingId, booking});
        queue.push_back(bookingId);
        for (auto& obs : observers) obs->onBookingWaitlisted(booking);
        return booking;
    }

    void cancelBooking(string bookingId) {
        auto it = bookings.find(bookingId);
        if (it == bookings.end() || it->second.status == "CANCELLED") {
            throw BookingNotFoundException("Unknown or already-cancelled booking: " + bookingId);
        }
        Booking& booking = it->second;
        if (booking.status == "WAITLISTED") {
            auto& queue = waitlists[booking.seatClass];
            queue.erase(remove(queue.begin(), queue.end(), bookingId), queue.end());
            booking.status = "CANCELLED";
            for (auto& obs : observers) obs->onBookingCancelled(booking);
            return;
        }
        Seat& seat = seats.at(booking.seatId);
        seat.status = SeatStatus::AVAILABLE;
        booking.status = "CANCELLED";
        for (auto& obs : observers) obs->onBookingCancelled(booking);
        auto& queue = waitlists[booking.seatClass];
        if (!queue.empty()) {
            string promotedId = queue.front();
            queue.erase(queue.begin());
            Booking& promoted = bookings.at(promotedId);
            int sold = soldCount(booking.seatClass);
            double fare = pricingStrategy->calculateFare(booking.seatClass, sold, capacity[booking.seatClass]);
            seat.status = SeatStatus::BOOKED;
            promoted.seatId = seat.seatId;
            promoted.fare = fare;
            promoted.status = "CONFIRMED";
            for (auto& obs : observers) obs->onWaitlistPromoted(promoted);
        }
    }
};

int main() {
    auto service = AirlineBookingService(make_shared<DemandBasedPricingStrategy>(), 1);
    service.addObserver(make_shared<ConsoleBookingObserver>());

    SeatFactory factory;
    service.addSeats(factory.createSeats(SeatClass::ECONOMY, 2));
    service.addSeats(factory.createSeats(SeatClass::BUSINESS, 1));

    Booking b1 = service.bookSeat("Alice", SeatClass::ECONOMY);
    Booking b2 = service.bookSeat("Bob", SeatClass::ECONOMY);
    Booking b3 = service.bookSeat("Carol", SeatClass::ECONOMY);

    service.cancelBooking(b1.bookingId);

    return 0;
}
